public class Types {
    public static void main(String[] args) {
        byte small = 100;
        short medium = 30_000;
        int count = 2_000_000_000;
        long big = 9_000_000_000L;
        float ratio = 2.5f;
        double precise = 3.14159;
        char letter = 'J';
        boolean ready = true;
        System.out.println(small + " " + medium + " " + count);
        System.out.println(big + " " + ratio + " " + precise);
        System.out.println(letter + " " + ready);
    }
}

int i = 42;
long l = i;                  // widening, automatic
double d = i;                // widening, automatic
System.out.println(l + " " + d);

double price = 9.99;
int whole = (int) price;     // narrowing: truncates toward zero
System.out.println(whole);
System.out.println((int) -9.99);
System.out.println(Math.round(price));

int big = 130;
byte b = (byte) big;         // keeps the low 8 bits: wraps around
System.out.println(b);

char c = 'A';
int code = c;                // a char is a number underneath
System.out.println(code);
System.out.println((char) (c + 2));

int max = Integer.MAX_VALUE;
System.out.println(max);
System.out.println(max + 1);
long safe = max + 1L;
System.out.println(safe);

String input = "42";
int parsed = Integer.parseInt(input);
double half = Double.parseDouble("2.5") / 2;
Integer boxed = parsed;          // autoboxing
int unboxed = boxed + 1;         // unboxing
System.out.println(parsed + 1);
System.out.println(input + 1);
System.out.println(half);
System.out.println(unboxed);
System.out.println(String.valueOf(3.0) + 4);

